import{_ as d,C as e,o as n,c as s,E as a,a2 as p}from"./chunks/framework.Cc8dJFaW.js";const l="/joinwell52/assets/sop-handoff-20261124/verdict-reader-v2.zh.svg",_=JSON.parse('{"title":"AI 数字员工接班，为什么复核也会判错？","description":"同一笔租金，两份报告的算式都正确，复核却把结果判反了。一组交接实验，追问数字员工该沿用哪版规程、何时可以改变，以及哪些旧成果还能继续使用。","frontmatter":{"title":"AI 数字员工接班，为什么复核也会判错？","description":"同一笔租金，两份报告的算式都正确，复核却把结果判反了。一组交接实验，追问数字员工该沿用哪版规程、何时可以改变，以及哪些旧成果还能继续使用。","cover":"/assets/covers/2026-11-24-sop-version-handoff-reader-v2.png","date":"2026-11-24","published_date":"2026-11-24","column":"digital-employee","category":"daily","article_type":"experiment-report","edition":"research-center","language":"zh-CN","lifecycle":"Published","publication_authorized":true,"lang":"zh-CN","pageClass":"six-governance-article"},"headers":[],"relativePath":"zh/research/2026-11-24-sop-version-handoff.md","filePath":"zh/research/2026-11-24-sop-version-handoff.md","lastUpdated":1795525048000}'),h={name:"zh/research/2026-11-24-sop-version-handoff.md"};function i(c,t,f,g,b,u){const r=e("ArticleCover"),o=e("ArticleTableScroll");return n(),s("div",null,[a(r,{image:"/assets/covers/2026-11-24-sop-version-handoff-reader-v2.png",kicker:"数字员工 · 交接与验收",title:"AI 数字员工接班，为什么复核也会判错？",summary:"同一笔租金，两份报告的算式都正确，复核却把结果判反了。一组交接实验，追问数字员工该沿用哪版规程、何时可以改变，以及哪些旧成果还能继续使用。",version:"2026-11-24",languageHref:"/en/research/2026-11-24-sop-version-handoff",languageLabel:"English"}),a(o,{language:"zh"}),t[0]||(t[0]=p('<h1 id="ai-数字员工接班-为什么复核也会判错" tabindex="-1">AI 数字员工接班，为什么复核也会判错？ <a class="header-anchor" href="#ai-数字员工接班-为什么复核也会判错" aria-label="Permalink to &quot;AI 数字员工接班，为什么复核也会判错？&quot;">​</a></h1><p>一张租金对账工单，应收 3,000 元，银行到账 2,700 元，另有 300 元暂定减免，申请尚未正式获批。</p><p>派工时的规程 V1 只认可正式批准的减免，因此这张单应当保留 300 元差额，等待确认。午后发布了 V2，允许把暂定减免也算进去。但工单留着一句明确的约定：<strong>本轮按派发时的规程完成。</strong></p><p>换班后，两份报告摆在复核者面前：</p><table tabindex="0"><thead><tr><th>报告</th><th>计算过程</th><th>结论</th></tr></thead><tbody><tr><td>零差额报告</td><td>3,000 − 2,700 − 300</td><td>账已对平</td></tr><tr><td>300 元差额报告</td><td>3,000 − 2,700</td><td>减免仍待确认</td></tr></tbody></table><p>按照工单约定，应当通过第二份。可在我们的实验里，按最新版重新计算的复核程序，恰好作出了相反判断：零差额报告通过，保留 300 元差额的报告被拒绝。</p><p>两份报告的减法都算得通。区别在于，哪一版规程适用于这张工单。<strong>执行和复核共同采用了一个未经确认的前提：规程发布了新版，这张在办工单就应该跟着改变。</strong></p><p>我们用这笔合成账开展了一组交接实验：由测试程序模拟对账和复核岗位，实际调用 CodeFlowMu 的任务等产品接口，通过 FCoP 保存工单、报告和复核记录。本轮没有调用大模型。实验先检查交接材料和产品接口能否支持明确的任务约定，再为真实 Agent 的自主执行与复核提出可检验的问题。实验说明与资料附于文末。</p><h2 id="复核重新算了一遍-为什么还会错" tabindex="-1">复核重新算了一遍，为什么还会错？ <a class="header-anchor" href="#复核重新算了一遍-为什么还会错" aria-label="Permalink to &quot;复核重新算了一遍，为什么还会错？&quot;">​</a></h2><p>复核程序打开 V2 后，看到暂定减免可以抵扣，就从 3,000 元中减去到账的 2,700 元，再减去 300 元，得到零。它随后用这个结果核对报告，自然接受零差额、拒绝 300 元差额。</p><p>计算过程中没有出现加减错误。复核漏掉的是一个更早的问题：<strong>这张工单是否已经获准改用 V2？</strong></p><p>为观察这个差别，实验设置了两种执行方式：一种直接读取当前发布的规程，另一种沿工单找回指定版本。分别在规程未更新、派工后更新到 V2 的条件下运行，每个组合重复三次，共产生 12 份报告。每份报告再接受两种复核：按当前规程复算金额，或按工单指定版本检查。</p><p>六次未更新的基线运行中，当前版就是工单指定的 V1。六份报告都留下 300 元差额，两种复核方式也都给出通过判定。这种平日看起来顺畅的流程，并没有暴露版本问题。</p><p>在另外六次更新对照中，直接读取 V2 的三次提交了零差额报告，找回 V1 的三次提交了 300 元差额报告。最新版复核通过了前三份，拒绝了后三份；按工单复核则拒绝前三份、通过后三份，结果与派工约定相符。<a href="/joinwell52/assets/sop-handoff-20261124/controlled-runs.json">逐轮结果</a></p><p><a href="/joinwell52/assets/sop-handoff-20261124/verdict-reader-v2.zh.svg"><img src="'+l+'" alt="同一份报告在两种复核策略下得到不同判定"></a></p><p><em>图中 A 为零差额报告，B 为保留 300 元差额的报告；每个组合重复三次。这里比较的是两套复核策略：最新版策略只复算金额，工单版策略还检查版本和文件指纹，各项检查的作用尚未分别测量。</em></p><p>这组对照显示，重新计算可以检查算式，却仍可能遗漏规则的适用范围。如果执行和复核都把“最新发布”当成“本单适用”，第二次计算就会重复第一个错误前提。</p><h2 id="接班者需要找回怎样的规程" tabindex="-1">接班者需要找回怎样的规程？ <a class="header-anchor" href="#接班者需要找回怎样的规程" aria-label="Permalink to &quot;接班者需要找回怎样的规程？&quot;">​</a></h2><p>这个问题最初来自 StaffDeck 的一处修复。它的旧数据库迁移逻辑可能改变规程编号，使已经发布的引用无法按原编号找回内容。修复保留公开编号，并在关联明确、没有冲突时恢复被旧逻辑改过的编号；新增回归测试则检查，数据库重新初始化后，原编号仍能找到规程，员工也仍能看到它。<a href="https://github.com/OpenBMB/StaffDeck/commit/389d5d331cf40eb5f0aae83c4fa24f4ed10b0003" target="_blank" rel="noreferrer">修复与回归测试</a></p><p>这项修复关注的是规程能否持续被找到。我们由此提出了另一个问题：即使编号一直有效，它今天打开的内容，是否适用于昨天派发、今天接手的工作？这一版本对照在 CodeFlowMu 中另行构造，并不是对 StaffDeck 版本治理能力的测试。</p><p>对接班者而言，查找规程至少涉及四件事：</p><table tabindex="0"><thead><tr><th>要确认的事情</th><th>要回答的问题</th></tr></thead><tbody><tr><td>规程标识</td><td>找的是哪份规程？</td></tr><tr><td>内容版本</td><td>读到的是哪一次发布的内容？</td></tr><tr><td>适用依据</td><td>为什么这张工单可以采用这一版？</td></tr><tr><td>原文可取回</td><td>需要核对时，能否实际读到对应内容？</td></tr></tbody></table><p>缺件测试单独检查了最后一项。我们保留工单中的 V1 引用和文件指纹，也保留可打开的 V2，只拿走 V1 原文。程序最终没有生成报告或复核记录，工单保持进行中。<a href="/joinwell52/assets/sop-handoff-20261124/controlled-runs.json">缺件记录</a></p><p>这个结果提醒我们：接班记录可以指出缺哪份材料，却不能凭一个指纹恢复规程条款。缺少适用原文时，应先补足依据；直接改读新版，会把“材料缺失”变成另一次未经确认的规则变更。</p><h2 id="如果这张工单本来就要改用新版呢" tabindex="-1">如果这张工单本来就要改用新版呢？ <a class="header-anchor" href="#如果这张工单本来就要改用新版呢" aria-label="Permalink to &quot;如果这张工单本来就要改用新版呢？&quot;">​</a></h2><p>工单约定沿用 V1 时，接班者需要找回 V1。但组织也可能决定，让一张正在办理的工单改按新规程继续。此时，交接要解决的问题又多了一层：哪张单获准改变，已经完成的工作还有哪些可以沿用？</p><p>续验使用两张独立工单，分别称为“待批工单”和“获批工单”。交班前，两张单都已核验 2,700 元的合成银行流水，按 V1 判断暂定减免可抵扣 0 元，并由另一测试身份复核、保存相关记录。两张单都还没有提交最终报告。</p><p>V2 发布后，管理员测试身份只批准其中一张改用新版，决定明确写着：<strong>保留已有流水核验，按 V2 重做减免判断。</strong> 另一张申请仍待审批。随后，更换执行和复核测试身份，重新通过任务接口读取工单及交班记录。</p><table tabindex="0"><thead><tr><th>接班后的结果</th><th>待批工单</th><th>获批工单</th></tr></thead><tbody><tr><td>使用的规程</td><td>V1</td><td>V2</td></tr><tr><td>再次核验银行流水</td><td>0 次</td><td>0 次</td></tr><tr><td>重新执行减免判断</td><td>0 次</td><td>1 次</td></tr><tr><td>重新复核减免判断</td><td>0 次</td><td>1 次</td></tr><tr><td>复核确认的差额</td><td>300 元</td><td>0 元</td></tr></tbody></table><p>记录显示，两张单各自的交接检查点在前后的文件指纹一致，流水核验都没有再次调用；获批工单只增加了一次减免判断和一次对应复核。两张单都保存了报告，并读回了正式复核记录。<a href="/joinwell52/assets/sop-handoff-20261124/selective-migration-runs.json">成对续验结果</a></p><p>两张单都能读到新版，却只有获批的那张改变了减免判断；两张单都更换了执行与复核身份，却都保留了原有流水核验。结果随具体工单上的决定变化，已经完成的工作也随交接保留下来。</p><p>在这组成对实验中，保留与重做的项目已经由决定明确列出，脚本负责执行。真实 Agent 能否自己识别变化涉及哪些步骤，是下一阶段需要验证的能力。</p><h2 id="旧结果留下来了-就一定还能用吗" tabindex="-1">旧结果留下来了，就一定还能用吗？ <a class="header-anchor" href="#旧结果留下来了-就一定还能用吗" aria-label="Permalink to &quot;旧结果留下来了，就一定还能用吗？&quot;">​</a></h2><p>假设银行后来撤回了那笔 2,700 元到账，原来的核验文件没有被改动，文件指纹当然仍然相同。但“这笔款已经到账”的旧结论，已经不能直接支持现在的对账结果。</p><p>因此，保留一份记录之后，还需要判断它在当前条件下是否成立。</p><p>在本例中，流水核验依据银行原件及核验条件；减免判断依据申请、批准状态和适用规程；最终差额依据前两项结果。如果只有减免口径发生变化，流水事实和核验条件仍然成立，就有理由沿用已有流水核验。若到账被撤回，受影响的就是另一部分工作。</p><p>文件指纹帮助我们确认记录内容有没有变化。原始材料、核验条件和适用规则，则帮助我们判断记录里的结论还能不能用。<strong>接班者知道旧结果为什么成立，才有依据决定继续使用还是重新核验。</strong></p><h2 id="数字员工接班-需要接过哪些依据" tabindex="-1">数字员工接班，需要接过哪些依据？ <a class="header-anchor" href="#数字员工接班-需要接过哪些依据" aria-label="Permalink to &quot;数字员工接班，需要接过哪些依据？&quot;">​</a></h2><p>两轮实验把交接需要的信息逐步展开了：先要知道本轮工作的约定，再要知道哪些决定改变了约定，最后还要知道已有结果是在什么条件下得到的。</p><p>对于执行 Agent，接手一张工单后，首先应当能查清要交付什么、原来采用哪版规程，以及是否存在对本任务、本轮生效的变更。一个新版文件的存在，无法单独说明当前工作是否应该跟着改变。</p><p>接下来，它要查看前面已经完成的工作。每项结果都应能追到原始材料、核验记录和当时的判断依据。这样，接手者才有条件决定哪些结果可以继续使用，哪些需要重做，哪些暂时缺少材料。</p><p>复核 Agent 面对的则是一份具体报告。它需要把报告中的金额、规则和证据重新联系起来，检查这些依据是否支持结论。执行者写下“流水已核验”，是一项需要核对的陈述；相应的原件和操作记录，才让这句话能够被检查。</p><p>在本次实现中，FCoP 将工单、报告和复核记录保存为可以相互引用的文件，CodeFlowMu 负责通过产品接口组织读取、提交和决定查询。岗位工作指引可以告诉 Agent 怎样查证，MCP 工具提供实际读取材料、执行操作和提交结果的入口。</p><p>这些部分各自提供判断所需的条件。操作回执可以表明工具返回过 V1 原文；减免是否符合 V1，仍需要结合条款检查。对账和复核岗位也因此有不同的职责：一方提出有依据的结果，另一方重新查证这些依据能否支持该结果。</p><h2 id="当所有-agent-都说-对-谁来检查前提" tabindex="-1">当所有 Agent 都说“对”，谁来检查前提？ <a class="header-anchor" href="#当所有-agent-都说-对-谁来检查前提" aria-label="Permalink to &quot;当所有 Agent 都说“对”，谁来检查前提？&quot;">​</a></h2><p>回到这笔账。工单要求沿用 V1 时，300 元应该留下；针对本单的换版决定生效后，这 300 元才可以按 V2 抵扣。同一笔业务、同样的金额，结论可以不同。判断的关键，是结果所依赖的规则和决定是否适用于当前任务。</p><p>这给多智能体协作留下了一个值得追问的问题：<strong>多个 Agent 得出相同答案，究竟是经过独立查证后的相互印证，还是同一个前提被重复接受？</strong> 执行者和复核者若都默认“最新版就是适用版”，更多次计算仍可能重复已有结论。要判断复核是否独立，还需要看它重新确认了哪些依据，以及它能否发现执行者遗漏的前提。</p><p>接班还提出了另一个问题。我们希望数字员工能够自主理解任务、选择方法，并决定哪些已有成果可以继续使用。这些能力让它有机会应对变化，也意味着它对任务的理解会影响实际行动。<strong>当接手的 Agent 调整做法时，怎样判断它是在继续履行原来的任务，还是已经重新定义了任务？</strong> 本例中，针对具体工单生效的决定给出了区分依据。面对更长的任务链、多次转派和多轮规则更新，这类依据需要随着工作继续传递。</p><p>这些问题还会影响我们怎样评价数字员工。复核者提出正确异议，可能让流程暂时停下来，也可能避免任务沿着错误前提继续推进。分歧本身并不能说明谁更可靠，反对意见同样需要证据；但一次有依据的暂停、补证或重新核验，应当能够在团队的评价中得到体现。</p><p>这笔账中的 300 元，最终把问题留给了数字员工系统的设计者：<strong>如果系统把“快速完成”和“一致通过”视为成功，那么那位查明依据、坚持说“先停一下”的数字员工，会被认定为更可靠，还是更低效？</strong></p><hr><h2 id="附件-实验说明与资料" tabindex="-1">附件：实验说明与资料 <a class="header-anchor" href="#附件-实验说明与资料" aria-label="Permalink to &quot;附件：实验说明与资料&quot;">​</a></h2><h3 id="实验范围" tabindex="-1">实验范围 <a class="header-anchor" href="#实验范围" aria-label="Permalink to &quot;实验范围&quot;">​</a></h3><p>第一轮包含 12 次执行、24 次复核判定，其中按工单指定版本进行的复核写入了 12 份正式复核记录；另有 1 次旧规程原件缺失测试。第二轮是两张工单的一组成对续验。</p><p>实验采用合成账目和测试身份，任务、报告等流程通过实际产品接口运行。规程解释、业务计算及选择哪些步骤重做，由测试程序完成，本轮没有调用大模型。</p><p>每个组合重复三次，用于检查受控路径的结果是否一致，不用于估计真实 Agent 的准确率。记录中的正常工单处于审查阶段，不等同于最终业务验收。</p><h3 id="原有实验资料" tabindex="-1">原有实验资料 <a class="header-anchor" href="#原有实验资料" aria-label="Permalink to &quot;原有实验资料&quot;">​</a></h3><p>以下继续引用原文章已经公开的资料：</p><ul><li><a href="/joinwell52/assets/sop-handoff-20261124/controlled-runs.json">12 次执行与 1 次缺件测试的逐轮记录</a>：工单指定版本、实际使用版本、文件指纹、报告金额、两种复核判定，以及报告和复核记录是否写入。</li><li><a href="/joinwell52/assets/sop-handoff-20261124/selective-migration-runs.json">两张工单的成对续验记录</a>：改用新版的决定状态、交接前后的检查点指纹、交接后的核验调用次数，以及报告与复核记录状态。</li><li><a href="https://github.com/OpenBMB/StaffDeck/commit/389d5d331cf40eb5f0aae83c4fa24f4ed10b0003" target="_blank" rel="noreferrer">StaffDeck 公开规程编号修复与回归测试</a>：本文所引用的规程标识稳定性修复。</li></ul><h3 id="版本记录" tabindex="-1">版本记录 <a class="header-anchor" href="#版本记录" aria-label="Permalink to &quot;版本记录&quot;">​</a></h3><p>两份结果摘要记录的 CodeFlowMu 产品代码基线为 <code>0d2d4e742ef2f3cb48e3ce09cc47f0c03053dc5f</code>，FCoP 为 <code>4.0.5</code>；第一轮同时记录 FCoP MCP 为 <code>4.0.5</code>。这些是公开结果摘要中的版本信息。</p>',61))])}const V=d(h,[["render",i]]);export{_ as __pageData,V as default};
